 select e.profile_id,r.id,case when e.employee_number='SYN-PROVIDER-10' then 'organisation' else 'global' end,case when e.employee_number='SYN-PROVIDER-10' then 'c2000000-0000-0000-0000-000000000003'::uuid end from private.employee_profiles e cross join private.roles r where e.employee_number like 'SYN-PROVIDER-%' and e.employee_number<>'SYN-PROVIDER-11' and r.code='synthetic_provider_network';
