create function pg_temp.actor(p_n integer) returns void language plpgsql as $$begin perform set_config('request.jwt.claim.sub',('c1000000-0000-0000-0000-'||lpad(p_n::text,12,'0')),true);end$$;
create function pg_temp.pc(p_action text,p_data jsonb default '{}',p_n integer default 3,p_provider text default 'provider') returns uuid language plpgsql as $$declare pid uuid;rev integer;begin
 perform pg_temp.actor(p_n);select id into pid from provider_ids where key=p_provider;rev=(public.read_provider(pid)->>'revision')::integer;
 return public.provider_command(pid,p_action,p_data||jsonb_build_object('expected_revision',rev,'reason','Synthetic provider test'),gen_random_uuid()::text);end$$;
create function pg_temp.cfg(p_action text,p_data jsonb,p_n integer default 3) returns uuid language plpgsql as $$begin perform pg_temp.actor(p_n);return public.provider_configuration(p_action,p_data||jsonb_build_object('reason','Synthetic configuration test'),gen_random_uuid()::text);end$$;
create function pg_temp.eligible() returns jsonb language sql as $$select public.provider_eligibility((select id from provider_ids where key='provider'),(select id from provider_ids where key='service'),(select id from provider_ids where key='zone'),now()+interval '1 day',now()+interval '1 day 1 hour','1')$$;
grant execute on function pg_temp.actor(integer),pg_temp.pc(text,jsonb,integer,text),pg_temp.cfg(text,jsonb,integer),pg_temp.eligible() to authenticated;
