select pg_temp.assert_true(jsonb_array_length(public.provider_activity((select id from provider_ids where key='provider'),null,null,5))=5,'Provider history has bounded staff projection');
select pg_temp.actor(1);
select pg_temp.assert_true(pg_temp.expect_error($q$select public.provider_activity((select id from provider_ids where key='provider'))$q$,'42501'),'Provider cannot read internal recruitment notes');
select pg_temp.actor(3);
select pg_temp.actor(1);
insert into provider_ids values('weekly',pg_temp.pc('weekly_schedule',jsonb_build_object('service_version_id',(select id from provider_ids where key='service'),'zone_id',(select id from provider_ids where key='zone'),'weekdays',jsonb_build_array(1,2,3,4,5),'local_start','09:00','local_end','17:00','valid_from',current_date+7,'valid_until',current_date+13),1));
select pg_temp.pc('revoke_schedule',jsonb_build_object('id',(select id from provider_ids where key='weekly')),1);
select pg_temp.actor(8);
select pg_temp.assert_true(pg_temp.expect_error($q$select public.apply_provider('{"provider_type":"processing_partner","organisation_id":"c2000000-0000-0000-0000-000000000002","source":"internal","reason":"Synthetic false attribution"}','synthetic-spoofed-source')$q$,'42501'),'Self applicant cannot claim trusted internal recruitment');
insert into provider_ids values('business_application',public.apply_provider('{"provider_type":"processing_partner","organisation_id":"c2000000-0000-0000-0000-000000000002","source":"online","reason":"Synthetic processing partner"}','synthetic-business-apply'));
insert into provider_ids select 'business',(public.list_providers()->0->>'id')::uuid;
select pg_temp.assert_true(public.read_provider((select id from provider_ids where key='business'))->>'type'='processing_partner','Business party distinct from an individual');
select pg_temp.assert_true(pg_temp.expect_error($q$select pg_temp.pc('availability',jsonb_build_object('service_version_id',(select id from provider_ids where key='service'),'start',now(),'end',now()+interval '1 day','kind','working'),8,'business')$q$,'42501'),'Applying as a member does not grant provider administrator rights');
select pg_temp.actor(3);
select pg_temp.pc('personnel',jsonb_build_object('profile_id','c1000000-0000-0000-0000-000000000008','role','administrator','valid_from',now()-interval '1 day'),3,'business');
select pg_temp.assert_true(pg_temp.expect_error($q$select pg_temp.pc('qualification',jsonb_build_object('kind','skill','code','cleaning','valid_from',now(),'subject_profile_id','c1000000-0000-0000-0000-000000000002'),3,'business')$q$,'23514'),'Business cannot attach foreign execution personnel qualifications');
select pg_temp.pc('personnel',jsonb_build_object('profile_id','c1000000-0000-0000-0000-000000000009','role','executing_worker','valid_from',now()-interval '1 day'),3,'business');
select pg_temp.pc('qualification',jsonb_build_object('kind','verification','code','identity','subject_profile_id','c1000000-0000-0000-0000-000000000009','document_id','c6000000-0000-0000-0000-000000000007','valid_from',now()-interval '1 day'),3,'business');
select pg_temp.actor(8);
select pg_temp.assert_true(pg_temp.expect_error($q$select public.provider_document_reference((select id from provider_ids where key='business'),'c6000000-0000-0000-0000-000000000007')$q$,'42501'),'Provider business administrator cannot download a worker personal identity document');
select pg_temp.actor(9);
select pg_temp.assert_true(public.provider_document_reference((select id from provider_ids where key='business'),'c6000000-0000-0000-0000-000000000007')->>'object_name'='synthetic-worker/identity','Worker retains access to their own linked identity evidence');
select pg_temp.assert_true(public.read_provider((select id from provider_ids where key='business'))->>'status'='applicant','Authorised worker reads own contracting organisation');
select pg_temp.assert_true(pg_temp.expect_error($q$select pg_temp.pc('availability',jsonb_build_object('service_version_id',(select id from provider_ids where key='service'),'start',now(),'end',now()+interval '1 day','kind','working'),9,'business')$q$,'42501'),'Executing worker cannot manage organisation-wide availability');
select pg_temp.actor(3);
select pg_temp.assert_true(public.provider_eligibility((select id from provider_ids where key='business'),(select id from provider_ids where key='service'),(select id from provider_ids where key='zone'),now()+interval '1 day',now()+interval '1 day 1 hour','1','c1000000-0000-0000-0000-000000000002')->'reasons' @> '[{"code":"worker_not_authorised"}]','Foreign worker rejected even when contracting party is an organisation');
select pg_temp.assert_true(not (public.provider_eligibility((select id from provider_ids where key='provider'),(select id from provider_ids where key='service'),(select id from provider_ids where key='zone'),now()+interval '1 day',now()+interval '1 day 1 hour','2')->>'eligible')::boolean,'Capacity unit demand above configured maximum rejected');
select pg_temp.assert_true(pg_temp.expect_error($q$select pg_temp.pc('capacity','{"unit":"bypass_jobs","units":"1"}')$q$,'23514'),'Individual cannot create parallel units to bypass shared capacity');
select pg_temp.assert_true(pg_temp.expect_error($q$select public.provider_command((select id from provider_ids where key='provider'),'suspend','{"expected_revision":1,"reason":"Stale update"}','synthetic-stale-revision')$q$,'40001'),'Stale provider revision rejected');
select pg_temp.assert_true(pg_temp.expect_error($q$select public.operational_event_worker('claim','{"limit":1,"lease_seconds":30,"max_attempts":3}')$q$,'42501'),'Ordinary users cannot claim event work');
reset role;
select pg_temp.assert_true((select count(*)=5 from private.provider_availability where schedule_id=(select id from provider_ids where key='weekly') and revoked_at is not null),'Weekly local schedule materialises five weekdays and revokes atomically');
select pg_temp.assert_true((select status='failed' and qualification_id is null from private.provider_training_enrolments where id=(select id from provider_ids where key='failed_enrolment')),'Failed attendance cannot create a certificate despite passing score');
update private.document_objects set scan_status='rejected' where id='c6000000-0000-0000-0000-000000000001';
set local role authenticated;
select pg_temp.actor(3);
select pg_temp.assert_true(not (pg_temp.eligible()->>'eligible')::boolean,'Changed evidence scan status rechecked before eligibility');
reset role;
update private.document_objects set scan_status='clean' where id='c6000000-0000-0000-0000-000000000001';
select pg_temp.assert_true(pg_temp.expect_error($q$update private.provider_history set reason='changed'$q$,'55000'),'Provider history append-only');
select pg_temp.assert_true(pg_temp.expect_error($q$update private.provider_requirement_sets set capacity_unit='changed' where id=(select id from provider_ids where key='policy')$q$,'55000'),'Approved eligibility terms immutable');
select pg_temp.assert_true(pg_temp.expect_error($q$update private.provider_engagements set unit_rate=20 where id=(select id from provider_ids where key='engagement')$q$,'55000'),'Approved private rate immutable');
select pg_temp.assert_true(pg_temp.expect_error($q$delete from private.operational_events$q$,'55000'),'Outbox events immutable');
select pg_temp.assert_true((select count(*) from private.operational_events)=(select count(*) from private.operational_event_deliveries),'Each event has transactional durable delivery receipt');
set local role service_role;
select set_config('request.jwt.claim.role','service_role',true);
insert into provider_ids select 'delivery',(public.operational_event_worker('claim','{"limit":1,"lease_seconds":30,"max_attempts":3}')->0->>'id')::uuid;
reset role;
insert into provider_ids select 'lease_token',lease_token from private.operational_event_deliveries where id=(select id from provider_ids where key='delivery');
set local role service_role;
select pg_temp.assert_true(pg_temp.expect_error($q$select public.operational_event_worker('ack',jsonb_build_object('id',(select id from provider_ids where key='delivery'),'token',gen_random_uuid()))$q$,'40001'),'Wrong worker lease token rejected');
select pg_temp.assert_true((public.operational_event_worker('ack',jsonb_build_object('id',(select id from provider_ids where key='delivery'),'token',(select id from provider_ids where key='lease_token')))->>'processed')::boolean,'Worker acknowledges actual leased event');
select pg_temp.assert_true((public.operational_event_worker('ack',jsonb_build_object('id',(select id from provider_ids where key='delivery'),'token',(select id from provider_ids where key='lease_token')))->>'processed')::boolean,'Worker acknowledgement retry idempotent');
reset role;
select pg_temp.assert_true((select status='processed' from private.operational_event_deliveries where id=(select id from provider_ids where key='delivery')),'Processing state persisted without claiming notification delivery');
select pg_temp.assert_true(not exists(select 1 from pg_tables where schemaname in ('public','private') and not rowsecurity),'Every application table retains RLS');
rollback;
